var i=`0847-pav-bhaji`;var t=`world-0847`;var n=`IN`;var s=`south-asia`;var r=4;var o=51;var g={en:`Pav Bhaji`,ua:`Пав бхаджі`};var d={en:`Pav Bhaji is a India dish made with potato, cauliflower, garden peas, carrot. This home-scale recipe assigns measured ingredients to the steps where they are used. Uses garam masala with coriander and amchur to approximate unavailable pav bhaji masala.`,ua:`Пав бхаджі, страва кухні країни Індія. Основні складники: картопля, цвітна капуста, зелений горошок, морква. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів. Гарам масала з коріандром та амчуром замінюють відсутню суміш пав-бхаджі-масала.`};var l=[{en:`Cook the listed ingredients in simmering water for about 22 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 22 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:22,i:[[`potato`,420,`g`],[`cauliflower`,230,`g`],[`garden-peas`,130,`g`],[`carrot`,180,`g`],[`water`,800,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 12 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 12 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:12,i:[[`yellow-onion`,200,`g`],[`tomato`,390,`g`],[`unsalted-butter`,85,`g`],[`garam-masala`,12,`g`],[`ground-coriander`,6,`g`],[`amchur-powder`,3,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:8,i:[]},{en:`Toast these ingredients over medium heat for about 6 minutes, turning frequently to prevent scorching.`,ua:`Підсмажуйте зазначені складники на середньому вогні приблизно 6 хвилин, часто перевертаючи, щоб не підгоріли.`,t:[`dry-toasting`],m:6,i:[[`bread-roll`,8,`pcs`],[`unsalted-butter`,50,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,20,`g`],[`lemon`,1,`pcs`]]}];var u={slug:i,id:t,country:`IN`,region:s,servings:4,minutes:51,title:g,text:d,steps:l};export{n as country,u as default,t as id,o as minutes,s as region,r as servings,i as slug,l as steps,d as text,g as title};